('multiple_choice','Anki-IPC-3001','A route to a /32 destination is known as a _____ route. (Choose one answer)','["A. host", "B. default gateway", "C. Non-broadcast", "D. Link-State Request (LSR)"]','[0]',NULL,10,NULL,NULL,NULL,'<div class="explanation-rich-content">\n  <div class="expl-card correct-card">\n    <h4 class="section-title-correct">✓ Correct Answer:</h4>\n    <p><strong>host</strong></p>\n  </div>\n  <div class="expl-card concept-card">\n    <div class="section-title-concept">📌 Source: Anki Flashcards — IP Connectivity (CCNA / Day 24 Flashcards - Dynamic Routing)</div>\n  </div>\n</div>'),
('multiple_choice','Anki-IPC-3002','A route to a network/subnet is known as a _____ route. (Choose one answer)','["A. exit-interface", "B. network", "C. 10 seconds", "D. router-id a.b.c.d"]','[1]',NULL,10,NULL,NULL,NULL,'<div class="explanation-rich-content">\n  <div class="expl-card correct-card">\n    <h4 class="section-title-correct">✓ Correct Answer:</h4>\n    <p><strong>network</strong></p>\n  </div>\n  <div class="expl-card concept-card">\n    <div class="section-title-concept">📌 Source: Anki Flashcards — IP Connectivity (CCNA / Day 24 Flashcards - Dynamic Routing)</div>\n  </div>\n</div>'),
('multiple_choice','Anki-IPC-3003','Routers can use _____ to advertise information about the routes they know to other routers. (Choose one answer)','["A. 170", "B. Distance Vector Link State", "C. dynamic routing protocols", "D. PPP / HDLC"]','[2]',NULL,10,NULL,NULL,NULL,'<div class="explanation-rich-content">\n  <div class="expl-card correct-card">\n    <h4 class="section-title-correct">✓ Correct Answer:</h4>\n    <p><strong>dynamic routing protocols</strong></p>\n  </div>\n  <div class="expl-card concept-card">\n    <div class="section-title-concept">📌 Source: Anki Flashcards — IP Connectivity (CCNA / Day 24 Flashcards - Dynamic Routing)</div>\n  </div>\n</div>'),
('multiple_choice','Anki-IPC-3004','If R1 learns multiple routes to the same destination from two different routing protocols, what is used to determine which route will be added to R1\'s routing table? (Choose one answer)','["A. Metric", "B. AD (Administrative Distance)", "C. next hop", "D. ip route ip-address netmask exit-interface"]','[1]',NULL,10,NULL,NULL,NULL,'<div class="explanation-rich-content">\n  <div class="expl-card correct-card">\n    <h4 class="section-title-correct">✓ Correct Answer:</h4>\n    <p><strong>AD (Administrative Distance)</strong></p>\n  </div>\n  <div class="expl-card concept-card">\n    <div class="section-title-concept">📌 Source: Anki Flashcards — IP Connectivity (CCNA / Day 24 Flashcards - Dynamic Routing)</div>\n  </div>\n</div>'),
('multiple_choice','Anki-IPC-3005','If R1 learns multiple routes to the same destination from the same routing protocol, what is used to determine which route will be added to R1\'s routing table? (Choose one answer)','["A. RIPv1 and RIPv2", "B. Metric", "C. encapsulation ppp", "D. network ip-address"]','[1]',NULL,10,NULL,NULL,NULL,'<div class="explanation-rich-content">\n  <div class="expl-card correct-card">\n    <h4 class="section-title-correct">✓ Correct Answer:</h4>\n    <p><strong>Metric</strong></p>\n  </div>\n  <div class="expl-card concept-card">\n    <div class="section-title-concept">📌 Source: Anki Flashcards — IP Connectivity (CCNA / Day 24 Flashcards - Dynamic Routing)</div>\n  </div>\n</div>'),
('multiple_choice','Anki-IPC-3006','Does a router prefer a lower or higher AD when selecting routes? (Choose one answer)','["A. DCE", "B. lower", "C. Exterior Gateway Protocol", "D. MTU"]','[1]',NULL,10,NULL,NULL,NULL,'<div class="explanation-rich-content">\n  <div class="expl-card correct-card">\n    <h4 class="section-title-correct">✓ Correct Answer:</h4>\n    <p><strong>lower</strong></p>\n  </div>\n  <div class="expl-card concept-card">\n    <div class="section-title-concept">📌 Source: Anki Flashcards — IP Connectivity (CCNA / Day 24 Flashcards - Dynamic Routing)</div>\n  </div>\n</div>'),
('multiple_choice','Anki-IPC-3007','Does a router prefer a lower or higher metric when selecting routes? (Choose one answer)','["A. ip route ip-address netmask exit-interface next-hop", "B. BGP", "C. lower", "D. RIPv1 and RIPv2"]','[2]',NULL,10,NULL,NULL,NULL,'<div class="explanation-rich-content">\n  <div class="expl-card correct-card">\n    <h4 class="section-title-correct">✓ Correct Answer:</h4>\n    <p><strong>lower</strong></p>\n  </div>\n  <div class="expl-card concept-card">\n    <div class="section-title-concept">📌 Source: Anki Flashcards — IP Connectivity (CCNA / Day 24 Flashcards - Dynamic Routing)</div>\n  </div>\n</div>'),
('multiple_choice','Anki-IPC-3008','Dynamic routing: What does IGP stand for? (Choose one answer)','["A. ip route ip-address netmask exit-interface", "B. K1 = 1 K2 = 0 K3 = 1 K4 = 0 K5 = 0", "C. Interior Gateway Protocol", "D. MTU"]','[2]',NULL,10,NULL,NULL,NULL,'<div class="explanation-rich-content">\n  <div class="expl-card correct-card">\n    <h4 class="section-title-correct">✓ Correct Answer:</h4>\n    <p><strong>Interior Gateway Protocol</strong></p>\n  </div>\n  <div class="expl-card concept-card">\n    <div class="section-title-concept">📌 Source: Anki Flashcards — IP Connectivity (CCNA / Day 24 Flashcards - Dynamic Routing)</div>\n  </div>\n</div>'),
